//! GlobeTranslucency, PerformanceDisplay, FrameRateMonitor and
//! ImageBasedLighting against the pinned CesiumJS traces in
//! `tests/data/scene-cpu-utilities.json` (generated by
//! `tools/cesium/generate-scene-cpu-utilities.mjs`).

use cesium_rs::core::*;
use cesium_rs::renderer::UniformFrame;
use cesium_rs::scene::frame_state::FrameResource;
use cesium_rs::scene::{
    Camera, CameraOptions, FrameRateMonitor, FrameRateMonitorOptions, FrameState, GlobeTranslucency,
    ImageBasedLighting, ImageBasedLightingConstructorOptions, PerformanceDisplay, SpecularEnvironmentCubeMap,
};
use serde_json::{json, Value};
use std::{cell::RefCell, collections::HashSet, rc::Rc};

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-cpu-utilities.json")).unwrap()
}

fn number(v: &Value) -> f64 {
    match v {
        Value::String(s) => match s.as_str() {
            "NaN" => f64::NAN,
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            "-0" => -0.0,
            other => panic!("unexpected number {other}"),
        },
        other => other.as_f64().unwrap(),
    }
}

/// The fixture's number encoding, so values compare as JSON.
fn enc(v: f64) -> Value {
    if v.is_nan() {
        json!("NaN")
    } else if v.is_infinite() {
        json!(if v > 0.0 { "Infinity" } else { "-Infinity" })
    } else if v == 0.0 && v.is_sign_negative() {
        json!("-0")
    } else if v.fract() == 0.0 && v.abs() < 1e15 {
        json!(v as i64)
    } else {
        json!(v)
    }
}

fn same(actual: &Value, expected: &Value) -> bool {
    match (actual, expected) {
        (Value::Number(a), Value::Number(e)) => a.as_f64().map(f64::to_bits) == e.as_f64().map(f64::to_bits),
        (Value::Array(a), Value::Array(e)) => a.len() == e.len() && a.iter().zip(e).all(|(a, e)| same(a, e)),
        (Value::Object(a), Value::Object(e)) => {
            a.len() == e.len() && a.iter().all(|(k, v)| e.get(k).is_some_and(|w| same(v, w)))
        }
        _ => actual == expected,
    }
}

macro_rules! assert_same {
    ($actual:expr, $expected:expr, $($context:tt)*) => {{
        let (actual, expected) = (&$actual, &$expected);
        assert!(same(actual, expected), "{}\n  actual: {actual}\nexpected: {expected}", format!($($context)*));
    }};
}

// --- GlobeTranslucency -------------------------------------------------------

fn translucency_state(t: &GlobeTranslucency) -> Value {
    let scalar =
        |s: Option<NearFarScalar>| s.map(|s| json!([enc(s.near), enc(s.near_value), enc(s.far), enc(s.far_value)]));
    let r = t.rectangle();
    json!({
        "enabled": t.enabled,
        "frontFaceAlpha": enc(t.front_face_alpha()),
        "backFaceAlpha": enc(t.back_face_alpha()),
        "frontFaceAlphaByDistance": scalar(t.front_face_alpha_by_distance()),
        "backFaceAlphaByDistance": scalar(t.back_face_alpha_by_distance()),
        "rectangle": [enc(r.west), enc(r.south), enc(r.east), enc(r.north)],
    })
}

#[test]
fn globe_translucency_matches_reference() {
    let fixture = fixture();
    let steps = fixture["globeTranslucency"].as_array().unwrap();
    let mut t = GlobeTranslucency::new();
    assert_same!(translucency_state(&t), steps[0]["state"], "initial");
    for step in &steps[1..] {
        let op = step["op"].as_str().unwrap();
        let value = &step["value"];
        let values = || value.as_array().unwrap().iter().map(number).collect::<Vec<_>>();
        let result = match op {
            "enabled" => {
                t.enabled = value.as_bool().unwrap();
                Ok(())
            }
            "frontFaceAlpha" => t.set_front_face_alpha(number(value)),
            "backFaceAlpha" => t.set_back_face_alpha(number(value)),
            "frontFaceAlphaByDistance" | "backFaceAlphaByDistance" => {
                let scalar = (!value.is_null()).then(|| {
                    let v = values();
                    NearFarScalar::new(v[0], v[1], v[2], v[3])
                });
                if op == "frontFaceAlphaByDistance" {
                    t.set_front_face_alpha_by_distance(scalar)
                } else {
                    t.set_back_face_alpha_by_distance(scalar)
                }
            }
            "rectangle" => {
                t.set_rectangle((!value.is_null()).then(|| {
                    let v = values();
                    Rectangle::new(v[0], v[1], v[2], v[3])
                }));
                Ok(())
            }
            other => panic!("unknown op {other}"),
        };
        let context = format!("{op} {value}");
        assert_eq!(result.err().map(|e| e.message), step["error"].as_str().map(String::from), "{context}");
        assert_same!(translucency_state(&t), step["state"], "{context}");
    }
}

// --- PerformanceDisplay ------------------------------------------------------

#[test]
fn performance_display_matches_reference() {
    let fixture = fixture();
    for script in fixture["performanceDisplay"].as_array().unwrap() {
        let mut display = PerformanceDisplay::new(number(&script["start"]));
        for frame in script["trace"].as_array().unwrap() {
            display.update(number(&frame["time"]), frame["rendered"].as_bool().unwrap());
            assert_eq!(display.fps_text, frame["fps"].as_str().unwrap(), "{frame}");
            assert_eq!(display.ms_text, frame["ms"].as_str().unwrap(), "{frame}");
        }
        display.set_throttled(true);
        assert_eq!(display.throttled_text(), script["throttledOn"].as_str().unwrap());
        display.set_throttled(false);
        assert_eq!(display.throttled_text(), script["throttledOff"].as_str().unwrap());
    }
}

// --- FrameRateMonitor --------------------------------------------------------

#[test]
fn frame_rate_monitor_matches_reference() {
    let fixture = fixture();
    let frm = &fixture["frameRateMonitor"];
    let defaults = FrameRateMonitorOptions::default();
    let d = &frm["defaults"];
    assert_eq!(defaults.sampling_window, number(&d["samplingWindow"]));
    assert_eq!(defaults.quiet_period, number(&d["quietPeriod"]));
    assert_eq!(defaults.warmup_period, number(&d["warmupPeriod"]));
    assert_eq!(defaults.minimum_frame_rate_during_warmup, number(&d["minimumFrameRateDuringWarmup"]));
    assert_eq!(defaults.minimum_frame_rate_after_warmup, number(&d["minimumFrameRateAfterWarmup"]));

    let mut events_seen = 0;
    for scenario in frm["scenarios"].as_array().unwrap() {
        let name = scenario["name"].as_str().unwrap();
        let o = &scenario["options"];
        let option = |key: &str, default: f64| o.get(key).map_or(default, number);
        let mut monitor = FrameRateMonitor::new(FrameRateMonitorOptions {
            sampling_window: option("samplingWindow", defaults.sampling_window),
            quiet_period: option("quietPeriod", defaults.quiet_period),
            warmup_period: option("warmupPeriod", defaults.warmup_period),
            minimum_frame_rate_during_warmup: option(
                "minimumFrameRateDuringWarmup",
                defaults.minimum_frame_rate_during_warmup,
            ),
            minimum_frame_rate_after_warmup: option(
                "minimumFrameRateAfterWarmup",
                defaults.minimum_frame_rate_after_warmup,
            ),
        });
        for (i, step) in scenario["trace"].as_array().unwrap().iter().enumerate() {
            match step["op"].as_str().unwrap() {
                "frame" => monitor.update(number(&step["value"])),
                "pause" => monitor.pause(),
                "unpause" => monitor.unpause(),
                "hidden" => monitor.visibility_changed(step["value"].as_bool().unwrap()),
                other => panic!("unknown op {other}"),
            }
            let mut events = Vec::new();
            while let Some(fps) = monitor.pop_low_frame_rate_event() {
                events.push(json!(["low", enc(fps)]));
            }
            while let Some(fps) = monitor.pop_nominal_frame_rate_event() {
                events.push(json!(["nominal", enc(fps)]));
            }
            events_seen += events.len();
            let context = format!("{name} step {i} {step}");
            assert_same!(json!(monitor.last_frames_per_second().map(enc)), step["fps"], "{context} fps");
            assert_same!(json!(events), step["events"], "{context} events");
        }
    }
    assert!(events_seen >= 8, "the traces raise both kinds of event");
}

// --- ImageBasedLighting ------------------------------------------------------

fn frame() -> FrameState {
    let mut camera = Camera::new(CameraOptions::new(8., 8.));
    let uniform = camera.uniform_camera();
    let culling = camera.frustum.compute_culling_volume(uniform.position, uniform.direction, uniform.up);
    FrameState::new(UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)), culling, [8, 8])
}

fn harmonics(name: &str) -> [Cartesian3; 9] {
    std::array::from_fn(|i| match name {
        "A" => Cartesian3::new(i as f64, 0., 0.),
        _ => Cartesian3::new(0., i as f64, 0.),
    })
}

#[derive(Default)]
struct Loader {
    ready: RefCell<HashSet<String>>,
    created: RefCell<Vec<String>>,
    destroyed: RefCell<Vec<String>>,
}

struct FakeCubeMap {
    url: String,
    ready: bool,
    loader: Rc<Loader>,
}

impl SpecularEnvironmentCubeMap for FakeCubeMap {
    fn url(&self) -> &str {
        &self.url
    }
    fn ready(&self) -> bool {
        self.ready
    }
    fn update(&mut self, _: &mut FrameState) {
        if self.loader.ready.borrow().contains(&self.url) {
            self.ready = true;
        }
    }
    fn destroy(&mut self) {
        self.loader.destroyed.borrow_mut().push(self.url.clone());
    }
}

#[test]
fn image_based_lighting_constructor_matches_reference() {
    let fixture = fixture();
    for case in fixture["imageBasedLighting"]["constructors"].as_array().unwrap() {
        let o = &case["options"];
        if o["sphericalHarmonicCoefficients"] == "short" {
            // Rust's `[Cartesian3; 9]` rules out Cesium's length error at compile time.
            assert!(case["error"].as_str().unwrap().contains("array of 9 Cartesian3"));
            continue;
        }
        let options = ImageBasedLightingConstructorOptions {
            image_based_lighting_factor: o.get("imageBasedLightingFactor").filter(|v| !v.is_null()).map(|v| {
                let v = v.as_array().unwrap();
                Cartesian2::new(number(&v[0]), number(&v[1]))
            }),
            spherical_harmonic_coefficients: o["sphericalHarmonicCoefficients"].as_str().map(harmonics),
            specular_environment_maps: o["specularEnvironmentMaps"].as_str().map(String::from),
        };
        match ImageBasedLighting::with_options(options) {
            Ok(ibl) => {
                assert!(case["error"].is_null(), "{case}");
                let f = ibl.image_based_lighting_factor();
                assert_same!(json!([enc(f.x), enc(f.y)]), case["factor"], "{case}");
                assert_eq!(json!(ibl.is_enabled()), case["enabled"], "{case}");
            }
            Err(e) => assert_eq!(Some(e.message.as_str()), case["error"].as_str(), "{case}"),
        }
    }
}

#[test]
fn image_based_lighting_traces_match_reference() {
    let fixture = fixture();
    let contexts: Vec<(&str, FrameResource, bool)> = vec![
        ("A", FrameResource::new("context A"), true),
        ("B", FrameResource::new("context B"), true),
        ("U", FrameResource::new("context U"), false),
    ];
    let default_maps = FrameResource::new("default.ktx2");
    for script in fixture["imageBasedLighting"]["traces"].as_array().unwrap() {
        let name = script["name"].as_str().unwrap();
        let loader = Rc::new(Loader::default());
        let mut ibl = ImageBasedLighting::new();
        let factory_loader = loader.clone();
        ibl.set_specular_environment_cube_map_factory(Box::new(move |url| {
            factory_loader.created.borrow_mut().push(url.to_string());
            Box::new(FakeCubeMap { url: url.into(), ready: false, loader: factory_loader.clone() })
        }));
        let mut frame = frame();
        for (i, step) in script["trace"].as_array().unwrap().iter().enumerate() {
            let a = &step["a"];
            let mut error = None;
            match step["op"].as_str().unwrap() {
                "factor" => {
                    let v = a.as_array().unwrap();
                    error = ibl
                        .set_image_based_lighting_factor(Cartesian2::new(number(&v[0]), number(&v[1])))
                        .err()
                        .map(|e| e.message);
                }
                "sh" => ibl.set_spherical_harmonic_coefficients(a.as_str().map(harmonics)),
                "maps" => ibl.set_specular_environment_maps(a.as_str().map(String::from)),
                "ready" => {
                    loader.ready.borrow_mut().insert(a.as_str().unwrap().into());
                }
                "destroy" => ibl.destroy(),
                "update" => {
                    let (_, context, supported) =
                        contexts.iter().find(|(n, ..)| *n == step["context"].as_str().unwrap()).unwrap();
                    frame.frame_number = a.as_u64().unwrap() as u32;
                    frame.context = Some(context.clone());
                    frame.context_capabilities.color_buffer_float = *supported;
                    frame.context_capabilities.floating_point_texture = *supported;
                    frame.context_capabilities.supports_texture_lod = *supported;
                    frame.specular_environment_maps =
                        step["frameMaps"].as_bool().unwrap().then(|| default_maps.clone());
                    frame.spherical_harmonic_coefficients =
                        step["frameSH"].as_bool().unwrap().then(|| harmonics("B").to_vec());
                    ibl.update(&mut frame);
                }
                other => panic!("unknown op {other}"),
            }
            let context = format!("{name} step {i} {}", step["op"]);
            assert_eq!(error.as_deref(), step["error"].as_str(), "{context}");
            assert_eq!(
                *loader.created.borrow(),
                step["created"].as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect::<Vec<_>>(),
                "{context} created"
            );
            assert_eq!(
                *loader.destroyed.borrow(),
                step["destroyed"].as_array().unwrap().iter().map(|v| v.as_str().unwrap()).collect::<Vec<_>>(),
                "{context} destroyed"
            );
            if step["op"] == "destroy" {
                assert!(ibl.is_destroyed());
                continue;
            }
            let f = ibl.image_based_lighting_factor();
            assert_same!(json!([enc(f.x), enc(f.y)]), step["factor"], "{context} factor");
            assert_eq!(json!(ibl.is_enabled()), step["enabled"], "{context} enabled");
            assert_eq!(json!(ibl.should_regenerate_shaders()), step["shouldRegenerateShaders"], "{context} regenerate");
            assert_eq!(json!(ibl.use_default_specular_maps()), step["useDefaultSpecularMaps"], "{context}");
            assert_eq!(json!(ibl.use_default_spherical_harmonics()), step["useDefaultSphericalHarmonics"], "{context}");
            assert_eq!(json!(ibl.use_specular_environment_maps()), step["useSpecularEnvironmentMaps"], "{context}");
            assert_eq!(ibl.specular_environment_cube_map().map(|m| m.url()), step["cubeMap"].as_str(), "{context}");
        }
    }
}
